'use strict';
// Record net wallet flows not already itemized by the called subsystem.
(()=>{
 const flow=x=>x.gross-x.tax+x.support+x.otherIncome-x.expenses-x.otherSpend-x.principal+x.shortfall;
 function wrap(api,key){if(typeof api?.[key]!=='function')return;const original=api[key];api[key]=function(s,...args){const book=Economy.accounts(s).current,cash=s.gold,before=flow(book),result=original.call(this,s,...args);if(book===Economy.accounts(s).current){const delta=Math.round(((s.gold-cash)-(flow(book)-before))*100)/100;if(delta)Economy.record(s,delta>0?'otherIncome':'otherSpend',Math.abs(delta))}return result}}
 for(const [api,keys] of [[Simulation,['automatic']],[Engine,['apply']],[LifeSpending,['spend','sellHouse']],[LifeChoices,['tick','buyItem','sellItem','adoptPet','petAction']],[LifeProjects,['start','resume','quarter']],[LifeBonds,['act']],[HumanOrigins,['support']],[Livelihood,['quarter','open','manage']],[Economy,['action']]])for(const k of keys)wrap(api,k);
 EVENTS.push({id:'family-pocket-gift',title:'ส่วนที่ผู้ดูแลกันไว้ให้',text:'{relative}เรียกคุณมาคุยเรื่องส่วนแบ่งที่กันไว้ คุณรับไว้ หรือฝากให้ใช้กับส่วนจำเป็นของกลุ่มก่อนได้',min:6,max:18,lifeOpportunity:true,familyGift:true,ecology:true,certain:true,choices:[{label:'รับไว้และถามว่าควรกันไว้ใช้อะไร',hint:'ส่วนแบ่งมาจากเงินหรือแหล่งดำรงชีวิตของผู้ดูแลจริง',effect:{bond:1},acceptGift:true,success:'ผู้ดูแลบอกที่มาของส่วนแบ่งก่อนมอบให้คุณ'},{label:'ฝากไว้กับส่วนจำเป็นของกลุ่มก่อน',hint:'ไม่รับเงินส่วนตัว · ความสัมพันธ์ +3',effect:{bond:3},declineGift:true,success:'คุณฝากส่วนแบ่งไว้ในแหล่งสำรอง ผู้ดูแลรับฟังเหตุผลของคุณ'}]});
EVENTS.push({id:'household-endowment',title:'ส่วนแบ่งจากทุนเดิมของกลุ่ม',text:'ผู้รับรองในกลุ่มชวนคุยเรื่องส่วนแบ่งที่ผูกกับสิทธิและพันธะ',min:18,lifeOpportunity:true,familyEndowment:true,ecology:true,certain:true,choices:[{label:'รับส่วนแบ่งและรับฟังภาระของกลุ่ม',hint:'รับจากทุนเดิมจริง · ความไว้ใจและพันธะมีผล',effect:{},acceptPatron:true,success:'คุณรับส่วนแบ่งพร้อมหน้าที่ที่ยังเลือกว่าจะตอบอย่างไร'},{label:'ให้เก็บทุนไว้ดูแลส่วนจำเป็นก่อน',hint:'ไม่รับเงินส่วนตัว · ความสัมพันธ์ +3',effect:{bond:3},success:'คุณให้กลุ่มกันทุนไว้สำหรับผู้ที่ยังจำเป็นต้องใช้'}]});
})();
